\set ON_ERROR_STOP on
BEGIN;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception '%',label;end if;end$$;
create function pg_temp.denied(command text,label text) returns void language plpgsql as $$begin begin execute command;exception when raise_exception or insufficient_privilege or check_violation then return;end;raise exception 'Expected denial: %',label;end$$;
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,aud,role) select ('cf000000-0000-4000-8000-00000000000'||n)::uuid,'billing-'||n||'@example.invalid',now(),'{"pms_admin_provisioned":true}','authenticated','authenticated' from generate_series(1,3)n;
insert into workspaces(id,name) values('cf000000-0000-4000-8000-000000000010','Billing fixture');
insert into workspace_members(workspace_id,user_id,role,display_name) select 'cf000000-0000-4000-8000-000000000010',('cf000000-0000-4000-8000-00000000000'||n)::uuid,case n when 1 then 'owner' when 2 then 'member' else 'client' end,'Person '||n from generate_series(1,3)n;
select set_config('request.jwt.claims','{"sub":"cf000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into projects(id,workspace_id,name,client_name) values('cf000000-0000-4000-8000-000000000020','cf000000-0000-4000-8000-000000000010','Billing project','Billing client'),('cf000000-0000-4000-8000-000000000021','cf000000-0000-4000-8000-000000000010','Other project','Other client');
insert into project_members values('cf000000-0000-4000-8000-000000000010','cf000000-0000-4000-8000-000000000020','cf000000-0000-4000-8000-000000000003','guest');
insert into client_documents(id,workspace_id,project_id,client_id,kind,title,status,content,total_cents,created_by) values('cf000000-0000-4000-8000-000000000030','cf000000-0000-4000-8000-000000000010','cf000000-0000-4000-8000-000000000020','cf000000-0000-4000-8000-000000000003','Project agreement','Scope','Approved','{"scope":"unchanged"}',100000,'cf000000-0000-4000-8000-000000000001');
insert into invoices(id,workspace_id,project_id,number,client_name,status,lines) values('cf000000-0000-4000-8000-000000000040','cf000000-0000-4000-8000-000000000010','cf000000-0000-4000-8000-000000000020','INV-fixture','Billing client','Sent','[{"description":"Scope","quantity":1,"rate":1000}]');
insert into client_payments(id,document_id,workspace_id,provider,provider_id,amount_cents) values('cf000000-0000-4000-8000-000000000050','cf000000-0000-4000-8000-000000000030','cf000000-0000-4000-8000-000000000010','Zelle','billing-fixture-payment',10000);
insert into invoice_receipts(id,workspace_id,invoice_id,amount,received_on,reference) values('cf000000-0000-4000-8000-000000000060','cf000000-0000-4000-8000-000000000010','cf000000-0000-4000-8000-000000000040',100,current_date,'Same transaction');
select save_billing_profile((select client_account_id from projects where id='cf000000-0000-4000-8000-000000000020'),0,'{"billing_name":"Billing client LLC","email":"accounts@example.invalid","address":"Test billing address","default_rate_cents":15000,"tax_rate":0,"tax_note":"Test tax note","contacts":[{"name":"Accounts","email":"ap@example.invalid","role":"Billing"}]}');
insert into estimates(id,workspace_id,project_id,number,client_name,lines) values('cf000000-0000-4000-8000-000000000041','cf000000-0000-4000-8000-000000000010','cf000000-0000-4000-8000-000000000020','EST-profile','Billing client','[{"description":"Fixture","quantity":1,"rate":1}]');
select save_billing_profile((select client_account_id from projects where id='cf000000-0000-4000-8000-000000000020'),1,'{"billing_name":"Changed name","email":"new@example.invalid","address":"New address","default_rate_cents":20000}');
select pg_temp.ok((select billing_profile_snapshot->>'billing_name'='Billing client LLC' from estimates where id='cf000000-0000-4000-8000-000000000041'),'profile snapshot is stable');
select pg_temp.denied($q$select save_billing_profile((select client_account_id from projects where id='cf000000-0000-4000-8000-000000000020'),1,'{"billing_name":"Stale","email":"a@example.invalid"}')$q$,'stale profile edit');
set local role authenticated;
select reconcile_billing_groups((select group_id from billing_sources where document_id='cf000000-0000-4000-8000-000000000030'),(select group_id from billing_sources where invoice_id='cf000000-0000-4000-8000-000000000040'),'Same full signed scope');
select pg_temp.ok((document_billing_balance('cf000000-0000-4000-8000-000000000030')->>'paid_cents')::bigint=20000,'two separate transactions counted before evidence match');
select reconcile_billing_payment('cf000000-0000-4000-8000-000000000060','cf000000-0000-4000-8000-000000000050','Bank reference confirms the same transaction');
select pg_temp.ok((document_billing_balance('cf000000-0000-4000-8000-000000000030')->>'paid_cents')::bigint=10000,'matched transaction counted once');
select pg_temp.denied($q$update invoices set lines='[{"quantity":1,"rate":2000}]' where id='cf000000-0000-4000-8000-000000000040'$q$,'linked financial basis immutable');
select pg_temp.denied($q$select record_invoice_receipt('cf000000-0000-4000-8000-000000000040',950,current_date,'Overpayment')$q$,'receipt respects combined balance');
select set_config('request.jwt.claims','{"sub":"cf000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select pg_temp.ok((select count(*)=0 from billing_profiles),'client cannot read profiles');
select pg_temp.denied($q$select billing_workspace('cf000000-0000-4000-8000-000000000010')$q$,'client cannot read consolidated internal ledger');
select pg_temp.ok((document_billing_balance('cf000000-0000-4000-8000-000000000030')->>'paid_cents')::bigint=10000,'client sees authorized balance');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
update client_payments set refunded_cents=2000 where id='cf000000-0000-4000-8000-000000000050';
select pg_temp.ok((billing_group_totals((select group_id from billing_sources where document_id='cf000000-0000-4000-8000-000000000030'))->>'paid_cents')::bigint=8000,'refund reduces matched net receipts');
insert into client_documents(id,workspace_id,project_id,client_id,kind,title,status,content,total_cents,created_by,previous_id,version) values('cf000000-0000-4000-8000-000000000031','cf000000-0000-4000-8000-000000000010','cf000000-0000-4000-8000-000000000020','cf000000-0000-4000-8000-000000000003','Project agreement','Scope revision','Shared','{"scope":"revised"}',120000,'cf000000-0000-4000-8000-000000000001','cf000000-0000-4000-8000-000000000030',2);
select pg_temp.ok((billing_group_totals((select group_id from billing_sources where document_id='cf000000-0000-4000-8000-000000000031'))->>'total_cents')::bigint=100000,'unapproved revision does not change obligation');
update client_documents set status='Approved' where id='cf000000-0000-4000-8000-000000000031';
select pg_temp.ok((billing_group_totals((select group_id from billing_sources where document_id='cf000000-0000-4000-8000-000000000031'))->>'balance_cents')::bigint=112000,'approved revision retains payment credit');
select pg_temp.ok((select content->>'scope'='unchanged' from client_documents where id='cf000000-0000-4000-8000-000000000030'),'approved historical content unchanged');
select pg_temp.ok(not has_function_privilege('anon','billing_workspace(uuid)','execute') and not has_function_privilege('authenticated','billing_group_totals(uuid)','execute'),'financial helper permissions');
select set_config('request.jwt.claims','{"sub":"cf000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
-- Checkout is idempotent across aliases and inaccessible to unrelated users.
insert into client_documents(id,workspace_id,project_id,client_id,kind,title,status,content,total_cents,created_by) values('cf000000-0000-4000-8000-000000000032','cf000000-0000-4000-8000-000000000010','cf000000-0000-4000-8000-000000000021','cf000000-0000-4000-8000-000000000003','Invoice','Unpaid scope','Approved','{}',50000,'cf000000-0000-4000-8000-000000000001');
select pg_temp.ok(claim_billing_checkout('cf000000-0000-4000-8000-000000000032')=claim_billing_checkout('cf000000-0000-4000-8000-000000000032'),'checkout retries retain exactly the same provider request');
select pg_temp.denied($q$select claim_billing_checkout('cf000000-0000-4000-8000-000000000030')$q$,'paid or obsolete document cannot start checkout');
select set_config('request.jwt.claims','{"sub":"cf000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select pg_temp.denied($q$select document_billing_balance('cf000000-0000-4000-8000-000000000032')$q$,'team member cannot read private client balance');
select pg_temp.denied($q$select claim_billing_checkout('cf000000-0000-4000-8000-000000000032')$q$,'team member cannot create private checkout');
select set_config('request.jwt.claims','{"sub":"cf000000-0000-4000-8000-999999999999","role":"authenticated","aal":"aal2"}',true);
select pg_temp.denied($q$select document_billing_balance('cf000000-0000-4000-8000-000000000032')$q$,'nonmember cannot read balance');
select set_config('request.jwt.claims','{"sub":"cf000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select delete_workspace('cf000000-0000-4000-8000-000000000010','Billing fixture');
select pg_temp.ok(not exists(select 1 from billing_groups where workspace_id='cf000000-0000-4000-8000-000000000010'),'workspace cleanup preserves lifecycle');
ROLLBACK;
